      "scope": "第一季基础关系样板；尚未覆盖全部出场人物，也未逐项复核所有关系。",
      "methodology": [
        "人物与演员由 TVmaze、第一季演职员资料交叉整理。TVmaze 存在角色重复、头衔跨季和童年演员错配，已人工修正本版涉及的项目。",
        "收录集数是保守的信息展示边界，不保证等于首次出场集数。人物介绍仅保留基础身份，不记载结局。",
        "关系表示截至观看进度已经揭示的联系，不等同于该集仍在持续的关系或人物当前状态。",
        "角色图来自 TVmaze、The Wire Wiki 和公开第一季分集截图。可确认的集数在照片下方注明；无法确认拍摄季数的如实标记。涉及后续状态的图片随观看进度解锁。不使用演员生活照替代角色图。",
        "这是资料核对中的原型，不宣称已达到逐帧核验的完全防剧透标准。外部资料页面可能包含全剧剧透。"
      ],
